CREATE TABLE public.staff_assignments (user_id uuid NOT NULL, responsibility text NOT NULL CHECK (responsibility IN ('forum','disputes')), assigned_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,responsibility));
GRANT SELECT ON public.staff_assignments TO authenticated;
GRANT ALL ON public.staff_assignments TO service_role;
ALTER TABLE public.staff_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_read ON public.staff_assignments FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.has_staff(_user_id uuid,_responsibility text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.staff_assignments WHERE user_id=_user_id AND responsibility=_responsibility); $$;
REVOKE ALL ON FUNCTION public.has_staff(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_staff(uuid,text) TO authenticated;
CREATE FUNCTION public.assign_staff(_user_id uuid,_responsibility text,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF _responsibility NOT IN ('forum','disputes') OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id) THEN RAISE EXCEPTION 'INVALID_STAFF'; END IF; IF _enabled THEN INSERT INTO public.staff_assignments(user_id,responsibility,assigned_by) VALUES(_user_id,_responsibility,auth.uid()) ON CONFLICT DO NOTHING; ELSE DELETE FROM public.staff_assignments WHERE user_id=_user_id AND responsibility=_responsibility; END IF; END $$;
REVOKE ALL ON FUNCTION public.assign_staff(uuid,text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.assign_staff(uuid,text,boolean) TO authenticated;
CREATE FUNCTION public.account_country(_user_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NULLIF(trim(country),'') FROM public.user_private_info WHERE user_id=_user_id; $$;
REVOKE ALL ON FUNCTION public.account_country(uuid) FROM PUBLIC;
CREATE FUNCTION public.same_community(_a uuid,_b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(public.account_country(_a)=public.account_country(_b),false) OR public.has_role(_a,'admin') OR public.has_role(_b,'admin'); $$;
REVOKE ALL ON FUNCTION public.same_community(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.same_community(uuid,uuid) TO authenticated;
ALTER TABLE public.forum_posts ADD COLUMN country text DEFAULT '';
UPDATE public.forum_posts SET country=COALESCE(public.account_country(author_id),'');
CREATE FUNCTION public.prepare_forum_post() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.author_id<>OLD.author_id OR NEW.country IS DISTINCT FROM OLD.country OR NEW.channel<>OLD.channel) THEN RAISE EXCEPTION 'IMMUTABLE_POST'; END IF; IF TG_OP='INSERT' THEN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_staff(auth.uid(),'forum')) THEN NEW.country:=public.account_country(auth.uid()); END IF; IF NULLIF(trim(NEW.country),'') IS NULL THEN RAISE EXCEPTION 'ACCOUNT_COUNTRY_REQUIRED'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER prepare_forum_post BEFORE INSERT OR UPDATE ON public.forum_posts FOR EACH ROW EXECUTE FUNCTION public.prepare_forum_post();
DROP POLICY forum_auth_read ON public.forum_posts;
DROP POLICY forum_insert ON public.forum_posts;
DROP POLICY forum_delete ON public.forum_posts;
CREATE POLICY forum_country_read ON public.forum_posts FOR SELECT TO authenticated USING(country=public.account_country(auth.uid()) OR public.has_role(auth.uid(),'admin') OR public.has_staff(auth.uid(),'forum'));
CREATE POLICY forum_country_insert ON public.forum_posts FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND (country=public.account_country(auth.uid()) OR public.has_role(auth.uid(),'admin') OR public.has_staff(auth.uid(),'forum')) AND (channel='general' OR ((channel='announcements') AND (public.has_role(auth.uid(),'admin') OR public.has_staff(auth.uid(),'forum')))));
CREATE POLICY forum_country_delete ON public.forum_posts FOR DELETE TO authenticated USING(author_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.has_staff(auth.uid(),'forum'));
CREATE FUNCTION public.is_dispute_conversation(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.conversations c JOIN public.orders o ON o.listing_id=c.listing_id AND o.buyer_id=c.buyer_id AND o.seller_id=c.seller_id JOIN public.disputes d ON d.order_id=o.id WHERE c.id=_id); $$;
REVOKE ALL ON FUNCTION public.is_dispute_conversation(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_dispute_conversation(uuid) TO authenticated;
CREATE FUNCTION public.can_access_conversation(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=_id AND (public.has_role(auth.uid(),'admin') OR (public.has_staff(auth.uid(),'disputes') AND public.is_dispute_conversation(c.id)) OR ((c.buyer_id=auth.uid() OR c.seller_id=auth.uid()) AND public.same_community(c.buyer_id,c.seller_id)))); $$;
REVOKE ALL ON FUNCTION public.can_access_conversation(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_conversation(uuid) TO authenticated;
CREATE POLICY conv_country_boundary ON public.conversations AS RESTRICTIVE FOR SELECT TO authenticated USING(public.can_access_conversation(id));
CREATE POLICY conv_country_create ON public.conversations AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.same_community(buyer_id,seller_id));
CREATE POLICY conv_country_update ON public.conversations AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.can_access_conversation(id)) WITH CHECK(public.same_community(buyer_id,seller_id));
CREATE POLICY conv_dispute_staff_read ON public.conversations FOR SELECT TO authenticated USING(public.has_staff(auth.uid(),'disputes') AND public.is_dispute_conversation(id));
CREATE FUNCTION public.lock_conversation_parties() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.buyer_id<>OLD.buyer_id OR NEW.seller_id<>OLD.seller_id OR NEW.listing_id<>OLD.listing_id THEN RAISE EXCEPTION 'IMMUTABLE_CONVERSATION'; END IF; RETURN NEW; END $$;
CREATE TRIGGER lock_conversation_parties BEFORE UPDATE ON public.conversations FOR EACH ROW EXECUTE FUNCTION public.lock_conversation_parties();
CREATE POLICY msg_country_boundary ON public.messages AS RESTRICTIVE FOR SELECT TO authenticated USING(public.can_access_conversation(conversation_id));
CREATE POLICY msg_country_send ON public.messages AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.can_access_conversation(conversation_id));
CREATE POLICY msg_dispute_staff_read ON public.messages FOR SELECT TO authenticated USING(public.has_staff(auth.uid(),'disputes') AND public.is_dispute_conversation(conversation_id));
CREATE POLICY msg_dispute_staff_send ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.has_staff(auth.uid(),'disputes') AND public.is_dispute_conversation(conversation_id));
CREATE POLICY disputes_staff_read ON public.disputes FOR SELECT TO authenticated USING(public.has_staff(auth.uid(),'disputes'));
CREATE POLICY orders_disputes_staff_read ON public.orders FOR SELECT TO authenticated USING(public.has_staff(auth.uid(),'disputes') AND EXISTS(SELECT 1 FROM public.disputes d WHERE d.order_id=orders.id));
DROP POLICY chat_files_read ON storage.objects;
DROP POLICY chat_files_insert ON storage.objects;
CREATE POLICY chat_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='chat-files' AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id::text=(storage.foldername(name))[1] AND public.can_access_conversation(c.id)));
CREATE POLICY chat_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='chat-files' AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id::text=(storage.foldername(name))[1] AND public.can_access_conversation(c.id)));
CREATE OR REPLACE FUNCTION public.admin_dispute_conversation(_order_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o record; cid uuid; BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_staff(auth.uid(),'disputes')) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF NOT EXISTS(SELECT 1 FROM public.disputes WHERE order_id=_order_id) THEN RAISE EXCEPTION 'DISPUTE_NOT_FOUND'; END IF; SELECT * INTO o FROM public.orders WHERE id=_order_id; SELECT id INTO cid FROM public.conversations WHERE listing_id=o.listing_id AND buyer_id=o.buyer_id AND seller_id=o.seller_id LIMIT 1; IF cid IS NULL THEN INSERT INTO public.conversations(listing_id,buyer_id,seller_id) VALUES(o.listing_id,o.buyer_id,o.seller_id) RETURNING id INTO cid; END IF; RETURN cid; END $$;
CREATE FUNCTION public.resolve_staff_dispute(_order_id uuid,_refund boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders%ROWTYPE; BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_staff(auth.uid(),'disputes')) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; SELECT * INTO o FROM public.orders WHERE id=_order_id FOR UPDATE; IF NOT FOUND OR o.status<>'disputed' OR NOT EXISTS(SELECT 1 FROM public.disputes WHERE order_id=o.id AND status='open') THEN RAISE EXCEPTION 'OPEN_DISPUTE_REQUIRED'; END IF; UPDATE public.wallets SET held=held-o.amount,balance=balance+CASE WHEN _refund THEN o.amount ELSE 0 END,updated_at=now() WHERE user_id=o.buyer_id AND held>=o.amount; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_ESCROW'; END IF; IF _refund THEN INSERT INTO public.wallet_transactions(user_id,type,amount,reference) VALUES(o.buyer_id,'escrow_refund',o.amount,o.id::text); UPDATE public.orders SET status='refunded',updated_at=now() WHERE id=o.id; UPDATE public.listings SET status='active' WHERE id=o.listing_id; ELSE UPDATE public.wallets SET balance=balance+o.amount-o.fee,updated_at=now() WHERE user_id=o.seller_id; IF NOT FOUND THEN RAISE EXCEPTION 'SELLER_WALLET_MISSING'; END IF; INSERT INTO public.wallet_transactions(user_id,type,amount,reference) VALUES(o.seller_id,'escrow_release',o.amount-o.fee,o.id::text),(o.seller_id,'fee',-o.fee,o.id::text); UPDATE public.orders SET status='completed',updated_at=now() WHERE id=o.id; UPDATE public.profiles SET sales_count=sales_count+1 WHERE id=o.seller_id; END IF; UPDATE public.disputes SET status='resolved',resolution=CASE WHEN _refund THEN 'استرجاع المبلغ للمشتري' ELSE 'تحرير المبلغ للبائع' END WHERE order_id=o.id AND status='open'; END $$;
REVOKE ALL ON FUNCTION public.resolve_staff_dispute(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resolve_staff_dispute(uuid,boolean) TO authenticated;